import{_ as n,P as i,d as s,e as r,x as t,q as o}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"Part 3 Universal Structural Grammar","description":"","frontmatter":{"title":"Part 3 Universal Structural Grammar","xkChars":22,"xkWords":3299,"xkLessons":{"3.3":{"title":"Trace the return and the difference it causes","lead":"Reception, effect, stability, and improvement are four separate claims.","explanation":["D2 names a return that changes a subsequent state, transition probability, timing, or constraint relative to no return or a blocked channel. Identify the earlier state or output, channel, receiving position, and changed field. A visible arrow in a diagram does not establish those links.","A receipt or archive establishes arrival or retention. It does not by itself establish the effect on the service or decision under inquiry. Causal attribution must address other changes that could explain the outcome; a before-and-after sequence alone may be insufficient.","A fixed controller can produce feedback without learning or lasting parameter change. A harmful signal can also be effective in this technical sense. Learning, convergence, correction, and beneficial outcomes each require their own conditions."],"distinctions":[{"leftTitle":"Receipt","leftText":"Evidence that the signal reached a recorded point.","rightTitle":"Effective feedback","rightText":"Evidence of a return-caused difference in a specified later field."}],"teachingExamples":[{"title":"A reply versus an earlier inspection","text":"An automated reply confirms receipt. If a complaint instead causes an inspection to occur earlier, the timing difference can support feedback even if the hazard is not yet removed.","assumptions":"Constructed complaint process; the timing effect is assumed to have adequate causal support.","boundary":"The example does not establish a real remedy or a beneficial net effect."}],"boundaries":["Do not interpret “effective” as necessarily truthful, timely, stable, or good.","A blocked-channel comparison does not authorize disrupting a real safety system."],"questionAnswers":[{"question":"Can fixed rules generate feedback without being retrained?","answer":"Yes. A returned observation can change the next action or state through a fixed rule. Learning is a further question.","basis":"Theory v2, §3.3, with the distinctions explained above."}],"caseLinks":[{"title":"Flint: receipt and risk assessment","href":"/en/cases/flint-water-feedback"},{"title":"Toyota: notification and response","href":"/en/cases/toyota-andon"}],"sourceRefs":[{"section":"3.3","startLine":515,"endLine":524}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-03#section-3-3","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§3.3; English reading edition, lines 515–524","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}],"model":"feedback"}}},"headers":[],"relativePath":"en/theory/part-03.md","filePath":"en/theory/part-03.md"}'),c={name:"en/theory/part-03.md"};function l(d,e,h,p,u,f){const a=i("SectionLesson");return s(),r("div",null,[e[0]||(e[0]=t("",1)),o(a,{section:"3.3"}),e[1]||(e[1]=t("",3))])}const g=n(c,[["render",l]]);export{b as __pageData,g as default};
